export function mountShell(){const toggle=document.getElementById('profileMenuToggle'),menu=document.getElementById('profileMenu'),slot=document.getElementById('menuAccountSlot');for(const id of ['accountBtn','exportBtn','communityAccount']){const item=document.getElementById(id);if(item)slot?.appendChild(item);}const close=()=>{menu.hidden=true;toggle.setAttribute('aria-expanded','false');};toggle.onclick=()=>{menu.hidden=!menu.hidden;toggle.setAttribute('aria-expanded',String(!menu.hidden));};document.addEventListener('click',e=>{if(!e.target.closest('.profile-dropdown'))close();});document.addEventListener('keydown',e=>{if(e.key==='Escape'){close();toggle.focus();}});menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',close));menu.querySelectorAll('[data-theme-choice]').forEach(b=>b.onclick=()=>{window.bytequestTheme(b.dataset.themeChoice);menu.querySelectorAll('[data-theme-choice]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));});return {setAccount(user,profile){const name=profile?.display_name||user?.user_metadata?.full_name||'Explorer';document.getElementById('menuName').textContent=name;const av=document.getElementById('menuAvatar');av.textContent=name.charAt(0).toUpperCase();if(profile?.avatar_url){const img=document.createElement('img');img.src=profile.avatar_url;img.alt='';img.referrerPolicy='no-referrer';av.replaceChildren(img);}}};}
